package com.watchalign.mobile;
import android.app.Activity;import android.content.Intent;import android.graphics.Color;import android.os.Bundle;import android.view.ViewGroup;import android.widget.*;import java.text.DateFormat;import java.util.*;
public final class HistoryActivity extends Activity {public void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(24,24,24,24);root.setBackgroundColor(Color.rgb(8,17,31));TextView h=new TextView(this);h.setText("Inspection history");h.setTextSize(26);h.setTextColor(Color.WHITE);root.addView(h);List<InspectionHistory.Record> all=InspectionHistory.list(this);if(all.isEmpty()){TextView e=new TextView(this);e.setText("No saved inspections yet.");e.setTextColor(Color.LTGRAY);root.addView(e);}for(InspectionHistory.Record r:all){Button x=new Button(this);x.setAllCaps(false);x.setText(r.model+"\n"+DateFormat.getDateTimeInstance().format(new Date(r.createdAt)));x.setOnClickListener(v->{if(InspectionHistory.reopen(r))startActivity(new Intent(this,FinalQcActivity.class));});root.addView(x,new LinearLayout.LayoutParams(-1,ViewGroup.LayoutParams.WRAP_CONTENT));}s.addView(root);setContentView(s);}}
